        SystemClock.sleep(850);ui(()->{check(stack[0].expanded&&stack[0].progress==1,"staggered expansion reaches full state");check(stack[0].getHeight()==stack[0].expandedHeight,"expanded cards reserve full nonoverlapping layout");stack[0].toggle();stack[0].toggle();stack[0].toggle();});
        SystemClock.sleep(850);ui(()->{check(!stack[0].expanded&&stack[0].progress==0,"rapid reversed taps settle to requested collapsed state");check(stack[0].getChildAt(1).getImportantForAccessibility()==View.IMPORTANT_FOR_ACCESSIBILITY_NO_HIDE_DESCENDANTS,"hidden cards are not duplicate screen reader targets");});capture("motion-home.png");
        ui(()->invoke("switchTab",new Class[]{int.class},1));SystemClock.sleep(100);ui(()->check(((FrameLayout)field(activity,"stage")).getChildCount()==2,"circular reveal temporarily retains previous page"));SystemClock.sleep(650);ui(()->{check(((FrameLayout)field(activity,"stage")).getChildCount()==1,"reveal releases previous page");check(find(activity.getWindow().getDecorView(),"交互动效")!=null,"reduce motion settings entry exists");invoke("switchTab",new Class[]{int.class},0);});SystemClock.sleep(600);
        ui(()->{invoke("switchTab",new Class[]{int.class},1);invoke("switchTab",new Class[]{int.class},0);});SystemClock.sleep(700);ui(()->check(((FrameLayout)field(activity,"stage")).getChildCount()==1,"interrupted tab reveals leave one live page"));
